create table if not exists public.passport_verification_tickets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, passport_public_id uuid not null references public.member_profiles(passport_public_id) on delete cascade, token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'), scopes text[] not null default array['identity.basic']::text[], purpose text not null default 'verify' check (purpose ~ '^[a-z0-9._:-]{3,48}$'), issued_at timestamptz not null default now(), expires_at timestamptz not null, consumed_at timestamptz, revoked_at timestamptz, check (expires_at > issued_at and expires_at <= issued_at + interval '10 minutes'), check (cardinality(scopes) between 1 and 12)); create index if not exists passport_verification_tickets_user_created_idx on public.passport_verification_tickets(user_id, issued_at desc); create index if not exists passport_verification_tickets_expiry_idx on public.passport_verification_tickets(expires_at) where consumed_at is null and revoked_at is null; alter table public.passport_verification_tickets enable row level security; revoke all on public.passport_verification_tickets from public, anon, authenticated; grant select, insert, update, delete on public.passport_verification_tickets to service_role; comment on table public.passport_verification_tickets is 'Service-only, short-lived Passport 3B verification tickets. Store token hashes only; never place PII or auth.users.id inside QR payloads.'; comment on column public.passport_verification_tickets.scopes is 'Explicit consent scope set. External verification defaults to identity.basic and must be minimized.';